import sys
sys.setrecursionlimit(10000)
def galgame(s):
 lines=s.splitlines();n=int(lines[0]);start,end=lines[1].split();graph={end:[]}
 for line in lines[2:]:
  words=line.split();u=words[0];count=int(words[1]);graph[u]=[(words[2+2*i],int(words[3+2*i])) for i in range(count)]
 nodes=set(graph)|{x for row in graph.values() for x,w in row};color={};order=[]
 # 显式DFS三色检查整个图，包含不可达分量。
 for root in nodes:
  if color.get(root):continue
  stack=[(root,False)]
  while stack:
   u,leave=stack.pop()
   if leave:color[u]=2;order.append(u);continue
   if color.get(u)==2:continue
   if color.get(u)==1:return 'WRONG INPUT'
   color[u]=1;stack.append((u,True))
   for v,w in reversed(graph.get(u,[])):
    if color.get(v)==1:return 'WRONG INPUT'
    if color.get(v)!=2:stack.append((v,False))
 best={end:0};choice={}
 for u in order:
  choices=[(best[v]+w,v) for v,w in graph.get(u,[]) if v in best]
  if choices:score=max(x[0] for x in choices);best[u]=score;choice[u]=min(v for value,v in choices if value==score)
 if start not in best:return 'WRONG INPUT'
 path=[start]
 while path[-1]!=end:path.append(choice[path[-1]])
 return str(best[start])+'\n'+' '.join(path)

sys.stdout.write(galgame(sys.stdin.read()) + "\n")

